import { useCallback, useEffect, useState } from 'react';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import { RECENTLY_VIEWED_HISTORY_MAX_STORED } from 'app/constants';

/**
 * Storage key backing the Recently Viewed interim history (see `useRecentlyViewedHistory`
 * below). Shared by both storage backends (`sessionStorage` for guests, `localStorage` for
 * registered shoppers) — safe, since the two are separate namespaces and can never collide.
 * Exported as a single named constant so every reader/writer agrees on it, per conventions.md's
 * no-magic-strings rule.
 *
 * Renamed from the pre-revision `RECENTLY_VIEWED_SESSION_KEY` (same literal value): this key now
 * holds a JSON-encoded array of product IDs, not a boolean flag string, so the old name no longer
 * described its contents.
 */
export const RECENTLY_VIEWED_HISTORY_STORAGE_KEY = 'zimm-recently-viewed';

const EMPTY_IDS: readonly string[] = [];

export type RecentlyViewedHistory = {
  hasRecentlyViewed: boolean;
  recentlyViewedIds: readonly string[];
  markProductViewed: (productId: string) => void;
};

/**
 * Reads and parses the stored ID list off a given `Storage`. Tolerant of every failure mode a
 * real browser can produce: the key missing entirely, `JSON.parse` failing on corrupt data, a
 * parsed value that isn't an array, or the storage access itself throwing (Safari private-
 * browsing mode throws on both `sessionStorage` and `localStorage` access, not just on write).
 * Every failure degrades to "no history" rather than propagating.
 */
const readStoredIds = (storage: Storage): string[] => {
  try {
    const raw = storage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
  } catch {
    return [];
  }
};

/**
 * Writes the given ID list to a `Storage`, JSON-encoded. Wrapped in try/catch: Safari private-
 * browsing mode throws on `setItem`, and a real device can also legitimately hit a storage quota.
 * Either way this degrades to "no write happens" rather than throwing further and breaking the
 * PDP view-tracking effect this is called from.
 *
 * @returns `true` if the write succeeded, `false` if it was silently swallowed.
 */
const writeStoredIds = (storage: Storage, ids: readonly string[]): boolean => {
  try {
    storage.setItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY, JSON.stringify(ids));
    return true;
  } catch {
    return false;
  }
};

/**
 * Moves `productId` to the front of `ids`, removing any existing occurrence first (never a
 * duplicate — a re-view of an already-seen product correctly becomes "most recent" again), then
 * trims to `RECENTLY_VIEWED_HISTORY_MAX_STORED`, oldest-first (i.e. from the tail).
 */
const dedupeAndPrepend = (ids: readonly string[], productId: string): string[] => {
  const withoutExisting = ids.filter((id) => id !== productId);
  return [productId, ...withoutExisting].slice(0, RECENTLY_VIEWED_HISTORY_MAX_STORED);
};

/**
 * SFCC-83/84 build plan step A4, **revised 2026-09-08** (Einstein is "Not Deployed" on every real
 * Zimmermann site — see the build plan's §2 "Interim data source"): this hook is the temporary,
 * browser-tracked stand-in for Einstein's own view-history tracking. It answers two questions:
 * "has this shopper viewed anything?" (`hasRecentlyViewed`, `recentlyViewedIds`) and "record that
 * this product was just viewed" (`markProductViewed`) — both backed by this browser's own
 * storage rather than a server-side recommendation engine.
 *
 * **The boolean logic, and why it changed from the pre-revision hook this file replaces
 * (`useRecentlyViewedGate.ts`):** the old design was
 * `hasRecentlyViewed = sessionFlagIsSet || isRegistered` — a deliberate short-circuit trusting
 * that a logged-in shopper has *some* server-side Einstein history even on a fresh device. That
 * assumption does not hold once Einstein is out of the loop: there is no server-side history left
 * to trust. Built with the old formula, every registered shopper would show
 * `hasRecentlyViewed: true` unconditionally — including one who has never viewed anything in this
 * interim system on any device — gating the rail *open* with zero real cards behind it. The
 * corrected formula is purely derived from this interim system's own tracked history, for guests
 * and registered shoppers alike:
 *
 * `hasRecentlyViewed = recentlyViewedIds.length > 0`
 *
 * `isRegistered` (from `useCustomerType()`, `@salesforce/commerce-sdk-react/hooks/
 * useCustomerType.js` — the same hook `@salesforce/retail-react-app/app/hooks/use-einstein.js:449`
 * already calls) still matters, just for a different purpose now: it selects *which* storage to
 * read/write, not whether to bypass the check.
 *
 * **Storage split:** `sessionStorage` for guests (genuinely session-scoped, cleared at session
 * end — AC 6, unchanged from the pre-revision design) and `localStorage` for registered shoppers.
 * The `localStorage` choice is a known, stated, temporary gap, not a fix for AC 7
 * ("available on login from any device"): `localStorage` survives closing the browser but is
 * still device-local, so it cannot satisfy cross-device continuity. See the build plan's §2 for
 * the full reasoning — this is carried in the PR body, not silently tested against one device and
 * called passing.
 *
 * SSR-safe by construction: both `recentlyViewedIds` and the derived `hasRecentlyViewed` start
 * empty/`false` on every render and are only ever resolved inside the effect below, so there is
 * no storage access during the render pass SSR reproduces — no hydration mismatch, since the rail
 * this gates does not exist on first paint either way.
 *
 * @returns `hasRecentlyViewed` — `true` once this browser has recorded at least one viewed
 *   product in the appropriate store, `false` otherwise (including on the very first render,
 *   before this hook's own effect has resolved). `recentlyViewedIds` — the stored IDs,
 *   most-recent-first. `markProductViewed` — call with a product ID to record a view; safe to
 *   call unconditionally, never throws.
 */
export const useRecentlyViewedHistory = (): RecentlyViewedHistory => {
  const { isRegistered } = useCustomerType();
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<readonly string[]>(EMPTY_IDS);

  useEffect(() => {
    const storage = isRegistered ? localStorage : sessionStorage;
    setRecentlyViewedIds(readStoredIds(storage));
  }, [isRegistered]);

  const markProductViewed = useCallback(
    (productId: string): void => {
      const storage = isRegistered ? localStorage : sessionStorage;
      const next = dedupeAndPrepend(readStoredIds(storage), productId);
      if (writeStoredIds(storage, next)) {
        setRecentlyViewedIds(next);
      }
    },
    [isRegistered],
  );

  return {
    hasRecentlyViewed: recentlyViewedIds.length > 0,
    recentlyViewedIds,
    markProductViewed,
  };
};

/**
 * The "given IDs, fetch real product data" half of SFCC-83/84's interim Recently Viewed data
 * source (build plan §2, "Interim data source" — Einstein is "Not Deployed" on every real
 * Zimmermann site, so this build ships against a browser-tracked view-history stand-in instead).
 * The companion piece is `useRecentlyViewedHistory`
 * (`overrides/app/hooks/useRecentlyViewedHistory.ts`), which supplies the `ids` this hook
 * consumes — every product this hook returns is real, live Commerce Cloud data; only the list of
 * *which* IDs to fetch is sourced from this browser's own tracked history rather than Einstein.
 *
 * Wraps `useProducts` (`@salesforce/commerce-sdk-react`, confirmed real export at
 * `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js`, re-exported from
 * the package root — the same hook already used at
 * `overrides/app/pages/product-detail/index.tsx:334`), which calls the Shopper Products
 * `getProducts` endpoint. Parameters (`allImages: true`, `perPricebook: true`, `expand: [
 * 'prices', 'promotions', 'images', 'variations']`) match the combination already confirmed
 * correct three independent times this build (Einstein's own `fetchRecProductDetails`
 * — `@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505` — the PLP quick-test mapper,
 * and the `zimmproductcard-live-demo` branch's real-product search call).
 *
 * **The 24-ID cap is a real, hard API limit, not a preference.** Confirmed directly in the SDK's
 * own doc comment: `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js:29`
 * — *"The maximum number of productIDs that can be requested are 24."* — restated independently
 * in `commerce-sdk-isomorphic`'s own type-declaration prose
 * (`node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts:58802`: *"hydrate a list of products
 * (max 24)"*). Marcel's explicit decision: cap to the first `GET_PRODUCTS_MAX_IDS_PER_REQUEST`
 * ids, don't batch into multiple requests — a shopper with more than 24 tracked IDs simply never
 * gets the tail of their history fetched by this hook.
 *
 * **SDK param widening for `ids`.** `getProductsQueryParameters.ids` types as `Array<string>`
 * throughout `commerce-sdk-isomorphic` (confirmed at `index.esm.d.ts:57797` and `:58753`), but the
 * real, working base SFCC call this build models (`use-einstein.js`'s `fetchRecProductDetails`)
 * passes a comma-joined string (`ids.join(',')`) straight through — the SDK forwards it verbatim
 * into the query string regardless of the declared array type. This file follows the exact same
 * precedent already used elsewhere in this codebase for this exact field:
 * `overrides/app/pages/product-detail/index.tsx:339`
 * (`ids: childVariantIds.join(',') as unknown as string[]`, commented there as "SDK param
 * widening").
 */
import { useProducts } from '@salesforce/commerce-sdk-react';
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';

/**
 * Hard per-request limit on the Shopper Products `getProducts` endpoint — see this file's own
 * docblock above for the two independent SDK citations confirming this number. Not a UX/product
 * choice, and not adjustable client-side.
 */
const GET_PRODUCTS_MAX_IDS_PER_REQUEST = 24;

export type RecentlyViewedProductFetchResult = {
  /**
   * Real Shopper Products data for as many of the requested (capped) `ids` as the API actually
   * returned, **re-ordered to match `ids`'s own order** — the API's own response order is not
   * documented or guaranteed to match request order, so this hook does the re-ordering rather
   * than assume it. An id the API didn't return at all (e.g. offline or deleted since it was
   * viewed) is silently dropped, not left as a hole in the array.
   */
  products: readonly ShopperProductsTypes.Product[];
  /** `true` only while a real fetch is in flight for a non-empty id list — deliberately `false`,
   *  not the underlying query's own (potentially permanently-pending) loading state, when there
   *  are no ids to fetch at all, since no request is ever made in that case. */
  isLoading: boolean;
};

/**
 * Given a list of product IDs (most-recent-first, per `useRecentlyViewedHistory`), fetches real,
 * live Commerce Cloud product data for them.
 *
 * @param ids - Product IDs to fetch, most-recent-first. A list longer than
 *   `GET_PRODUCTS_MAX_IDS_PER_REQUEST` is truncated to the first N (Marcel's cap-don't-batch
 *   decision) — the endpoint itself has no way to serve more in a single call.
 * @returns `products` — real product data for the requested ids, re-ordered to match `ids` and
 *   with any id the API didn't return dropped. `isLoading` — whether a real fetch is in flight.
 */
export const useRecentlyViewedProductFetch = (ids: readonly string[]): RecentlyViewedProductFetchResult => {
  const cappedIds = ids.slice(0, GET_PRODUCTS_MAX_IDS_PER_REQUEST);

  const { data, isLoading: queryIsLoading } = useProducts(
    {
      parameters: {
        // SDK param widening -- see this file's own docblock for why a comma-joined string is
        // correct here despite the declared `Array<string>` type.
        ids: cappedIds.join(',') as unknown as string[],
        allImages: true,
        perPricebook: true,
        expand: ['prices', 'promotions', 'images', 'variations'],
      },
    },
    {
      // Matches the existing precedent at product-detail/index.tsx:347 for this same hook: don't
      // fire a request at all when there's nothing to ask for.
      enabled: cappedIds.length > 0,
    },
  );

  const productsById = new Map((data?.data ?? []).map((product) => [product.id, product] as const));
  const products = cappedIds
    .map((id) => productsById.get(id))
    .filter((product): product is ShopperProductsTypes.Product => product !== undefined);

  return {
    products,
    // A disabled query (no ids) never transitions out of its initial loading state on some
    // TanStack Query versions/configurations -- AND against `cappedIds.length > 0` so "loading"
    // never lies about a fetch that was never actually started.
    isLoading: cappedIds.length > 0 && queryIsLoading,
  };
};

