/**
 * SFCC-83/84 build plan step A6 — asserts only this component's own branch-selection contract
 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given a `recommender` and
 * `useRecentlyViewedGate`'s return value, does it render `ZimmRecentlyViewedRail`, `ProductScroller`,
 * or nothing at all. `ZimmRecentlyViewedRail`, `ProductScroller`, `useRecentlyViewedGate`, and
 * `selectRecentlyViewedCard` are all mocked at the smallest surface — their own internals already
 * have their own coverage elsewhere (`zimmRecentlyViewedRail/index.test.tsx`,
 * `recentlyViewedCard.test.ts`; base `ProductScroller` is untouched vendor code).
 */
import React from 'react';
import { describe, test, expect, vi, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
import theme from 'app/theme';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { useRecentlyViewedGate } from '../../hooks/useRecentlyViewedGate';
import { selectRecentlyViewedCard, type RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
import RecommendedProducts, { type RecommendedProductsProps } from '.';

// Smallest-surface mocks throughout — see module docblock above for why each of these is safe to
// stub rather than exercise for real in this file.

vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
  default: () => ({ sendViewRecommendations: vi.fn() }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
  useCurrentCustomer: () => ({ data: { customerId: 'test-customer-id' } }),
}));

// Real use-intersection-observer.js already degrades to `true` under jsdom (no global
// IntersectionObserver), but stubbed anyway per this step's own brief, for a deterministic
// `isOnScreen` this file doesn't otherwise need to reason about.
vi.mock('@salesforce/retail-react-app/app/hooks/use-intersection-observer', () => ({
  default: () => false,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
  useWishList: () => ({ data: undefined }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: () => vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
  default: () => vi.fn(),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperCustomersMutation: () => ({ mutateAsync: vi.fn() }),
}));

// ProductScroller is a real `forwardRef` component (product-scroller/index.jsx) — mocked as one
// too, rather than a plain function, so `<ProductScroller ref={ref} .../>` doesn't trip React's
// "function components cannot be given refs" warning for no reason.
vi.mock('@salesforce/retail-react-app/app/components/product-scroller', () => ({
  default: React.forwardRef(function ProductScrollerStub(_props: unknown, ref: React.Ref<HTMLDivElement>) {
    return <div ref={ref} data-testid="product-scroller-stub" />;
  }),
}));

// Relative paths matching index.tsx's own imports exactly — see overrideStyling.md's
// "Importing an already-overridden component" doctrine cited there.
vi.mock('../ui-kits/organisms/zimmRecentlyViewedRail', () => ({
  ZimmRecentlyViewedRail: vi.fn(() => <div data-testid="zimm-recently-viewed-rail-stub" />),
}));

vi.mock('../../hooks/useRecentlyViewedGate', () => ({
  useRecentlyViewedGate: vi.fn(),
}));

vi.mock('../../utils/recentlyViewedCard', () => ({
  selectRecentlyViewedCard: vi.fn(),
}));

const mockUseEinstein = vi.mocked(useEinstein);
const mockUseRecentlyViewedGate = vi.mocked(useRecentlyViewedGate);
const mockSelectRecentlyViewedCard = vi.mocked(selectRecentlyViewedCard);
const mockZimmRecentlyViewedRail = vi.mocked(ZimmRecentlyViewedRail);

// Two recs, deliberately different `productId`s, so a mapping/filtering bug (wrong rec picked,
// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
// same doctrine recentlyViewedCard.test.ts documents as "G1".
const mockRecommendations = {
  recommenderName: 'viewed-recently-einstein',
  recoUUID: 'test-reco-uuid',
  displayMessage: 'Recently Viewed',
  recs: [
    { productId: 'rec-1', name: 'Product One' } as RecentlyViewedProduct,
    { productId: 'rec-2', name: 'Product Two' } as RecentlyViewedProduct,
  ],
};

const renderRecommendedProducts = (props: Partial<RecommendedProductsProps> = {}) =>
  render(
    <IntlProvider locale="en-AU" messages={{}}>
      <ChakraProvider theme={theme}>
        <RecommendedProducts recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE} {...props} />
      </ChakraProvider>
    </IntlProvider>,
  );

afterEach(() => {
  vi.clearAllMocks();
});

describe('RecommendedProducts — Recently Viewed branch (SFCC-83/84, build plan A6)', () => {
  test('recommender=PDP_RECENTLY_VIEWED + gate true renders ZimmRecentlyViewedRail, not ProductScroller', () => {
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: mockRecommendations,
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    mockUseRecentlyViewedGate.mockReturnValue(true);
    // rec-2 deliberately maps to `null` (e.g. no usable image/name) — proves the branch's own
    // `.filter()` drops it instead of forwarding a null card or crashing.
    mockSelectRecentlyViewedCard.mockImplementation((product) =>
      product?.productId === 'rec-2'
        ? null
        : {
            id: product?.productId ?? '',
            href: `/product/${product?.productId ?? ''}`,
            name: product?.name ?? '',
            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
            currentPrice: undefined,
          },
    );

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    expect(screen.getByTestId('zimm-recently-viewed-rail-stub')).toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();

    // Branch's own mapping contract (not the rail's internals): the null-mapped rec is dropped,
    // the surviving card carries the container-assigned `headingLevel`/`variation`, and the
    // title falls back to the Einstein response's own `displayMessage` when no `title` prop is
    // passed — matching the ProductScroller branch's own identical fallback expression.
    expect(mockZimmRecentlyViewedRail).toHaveBeenCalledTimes(1);
    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
    expect(railProps.title).toBe('Recently Viewed');
    expect(railProps.cards).toHaveLength(1);
    expect(railProps.cards[0]).toMatchObject({
      id: 'rec-1',
      headingLevel: 'h3',
      variation: 'recentlyViewed',
    });
  });

  test.each([
    ['gate true', true],
    ['gate false', false],
  ])(
    'any other recommender renders ProductScroller, not ZimmRecentlyViewedRail, regardless of the gate (%s)',
    (_label, gateValue) => {
      mockUseEinstein.mockReturnValue({
        isLoading: false,
        recommendations: mockRecommendations,
        getZoneRecommendations: vi.fn(),
        getRecommendations: vi.fn(),
        sendClickReco: vi.fn(),
        sendViewReco: vi.fn(),
      });
      mockUseRecentlyViewedGate.mockReturnValue(gateValue);

      renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });

      expect(screen.getByTestId('product-scroller-stub')).toBeInTheDocument();
      expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
      expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
    },
  );

  test('recommender=PDP_RECENTLY_VIEWED + gate false renders null (AC 8): no rail, no scroller', () => {
    mockUseEinstein.mockReturnValue({
      isLoading: false,
      recommendations: mockRecommendations,
      getZoneRecommendations: vi.fn(),
      getRecommendations: vi.fn(),
      sendClickReco: vi.fn(),
      sendViewReco: vi.fn(),
    });
    mockUseRecentlyViewedGate.mockReturnValue(false);

    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });

    // Neither branch's component rendered — the component itself returns `null` here. Not
    // asserted via `container.toBeEmptyDOMElement()`: ChakraProvider always injects its own
    // internal `<span id="__chakra_env">` marker regardless of what this component renders, so
    // an empty-container check would be asserting on Chakra's own internals, not this
    // component's contract.
    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
  });
});

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_MAX_ITEMS } from 'app/constants';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_MAX_ITEMS` regardless of length; see
   * that constant's own comment (app/constants/index.ts) for why the cap has to live here rather
   * than in the request that produced this array.
   */
  cards: readonly ZimmProductCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper), gating this
 * component's visibility (A4's `hasRecentlyViewed`), and supplying `title`/`seeAllLabel` copy.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a horizontally scrollable `group` of `ZimmProductCard`s. No rail-level arrow buttons —
 * `ZimmProductCardMedia` already carries its own intra-card carousel arrows, and a second set at
 * the rail level would collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for
 * the Figma node evidence). Paging is native horizontal scroll with CSS scroll-snap only.
 *
 * `cards` is typed as the full `ZimmProductCardProps` union, matching this step's own given
 * component contract verbatim — this component therefore spreads each entry straight into
 * `ZimmProductCard` (`<ZimmProductCard {...card} />`) rather than forcing
 * `variation: 'recentlyViewed'` onto every card itself. In real usage every entry already carries
 * that variation by construction (A3's mapper produces `recentlyViewed`-shaped cards, matching
 * `variation: 'recentlyViewed'` in the type union — see zimmProductCard/index.tsx's
 * `ZimmProductCardRecentlyViewedVariation`) — this component trusts that contract rather than
 * re-asserting it, consistent with staying purely presentational.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — see
  // RECENTLY_VIEWED_RAIL_MAX_ITEMS's own comment (app/constants/index.ts): the Einstein API this
  // data ultimately comes from does not itself honour a requested limit. A slice, never a sort —
  // order is otherwise untouched (AC 2).
  const visibleCards = cards.slice(0, RECENTLY_VIEWED_RAIL_MAX_ITEMS);

  // Second guard behind A4's own visibility gate, which lives in the container, not here — an
  // empty rail renders nothing at all, not an empty shell.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        <chakra.span textStyle="heading3">{title}</chakra.span>
        {seeAllHref && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

